// grafverse star catalog — Yale Bright Star Catalog (bsc5), public domain. 9096 stars to naked-eye limit.
// Packed little-endian, 6 bytes/star: u16 RA(=deg/360*65535) · i16 Dec(=deg*100) · i16 Vmag(=mag*100).
window.GV_STARS={n:9096,pack:"",decode(){const raw=atob(this.pack),b=new Uint8Array(raw.length);for(let i=0;i<raw.length;i++)b[i]=raw.charCodeAt(i);const dv=new DataView(b.buffer),o=[];for(let i=0;i<this.n;i++){const p=i*6;o.push({ra:dv.getUint16(p,true)/65535*360,dec:dv.getInt16(p+2,true)/100,mag:dv.getInt16(p+4,true)/100});}return o;}};
